const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

export interface ApiResponse<T> {
  success: boolean;
  data?: T;
  message?: string;
}

export const api = {
  // Authentication - FIXED
  async login(regNo: string, password: string): Promise<ApiResponse<{ token: string; user: any }>> {
    try {
      const response = await fetch(`${API_BASE_URL}/auth/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ regNo, password })
      });
      const data = await response.json();
      return data;
    } catch (error) {
      // Fallback for demo if backend not reachable or fails
      if (regNo === 'ADMIN001' && password === 'admin123') {
        return {
          success: true,
          data: {
            token: 'demo-token-' + Date.now(),
            user: {
              id: '1',
              name: 'System Admin',
              regNo: 'ADMIN001',
              role: 'admin',
              department: 'Parking Management'
            }
          }
        };
      }
      return { success: false, message: 'Login failed' };
    }
  },

  // Dashboard Analytics
  async getDashboardStats(): Promise<ApiResponse<any>> {
    return {
      success: true,
      data: {
        totalUsers: 245,
        totalParkingAreas: 8,
        totalSlots: 320,
        occupiedSlots: 245,
        availableSlots: 75,
        todayEntries: 156,
        todayExits: 128,
        revenueToday: 2450,
      }
    };
  },

  // Parking Areas
  async getParkingAreas(): Promise<ApiResponse<any[]>> {
    try {
      const response = await fetch(`${API_BASE_URL}/booking/areas`);
      const resData = await response.json();
      return {
        success: resData.success,
        data: resData.areas, // Map areas to data
        message: resData.message
      };
    } catch (error) {
      return { success: false, message: "Failed to fetch areas" };
    }
  },

  async createParkingArea(payload: any): Promise<ApiResponse<any>> {
    try {
      // Get token from localStorage (set by AuthContext)
      const token = localStorage.getItem('token');

      const response = await fetch(`${API_BASE_URL}/admin/create-area`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(payload)
      });
      return await response.json();
    } catch (error) {
      return { success: false, message: "Failed to create area" };
    }
  },

  // Users Management
  async getUsers(): Promise<ApiResponse<any[]>> {
    return {
      success: true,
      data: [
        { id: '1', name: 'John Doe', email: 'john@university.edu', role: 'student', status: 'active' },
        { id: '2', name: 'Jane Smith', email: 'jane@university.edu', role: 'faculty', status: 'active' },
      ]
    };
  },
};
